head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.fr_SecuGrpId;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.clickBzProcsNo;
scwin.clickListProcsStatCd;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.vScrenID = "ULDSTF05980.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    var urldep = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.DataID = encodeURI(urldep);
    dts_DEP_CD.Reset();
    var urlemp = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.DataID = encodeURI(urlemp);
    dts_EMP_NO.Reset();
    dts_FORM_CD.DataID = "/CodeAction.do?method=listListingFormCd&inputMessageId=LISTING_FROM_CD_OUT" + "&For=R&LD_MKT_TP_CD=" + scwin.gLdMktTp;
    dts_FORM_CD.Reset();
    dts_LIST_BZ_TP_CD.DataID = "/CodeAction.do?method=listListingBZTpCd&inputMessageId=LISTING_FROM_CD_OUT" + "&For=R&LD_MKT_TP_CD=" + scwin.gDepCd;
    dts_LIST_BZ_TP_CD.Reset();
    $c.stf.setObjectValue(cmb_DEP_CD, js_dep_cd);
    $c.stf.setObjectValue(cmb_EMP_NO, js_emp_no);
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD);
    arrPar[1] = $c.stf.getObjectValue(txb_COM_NM);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsur = function(arrPar) {
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM.setValue(arrPar[0].COM_NM);
};
scwin.fn_Search = function() {
    var url = "/administrativeIssue.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchSpacReleasAct";
    url += "&inputMessageId=SPACRELEAS_MST_INOUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&PROCS_STAT_CD=" + $c.stf.getObjectValue(rdo_PROCS_STAT_CD);
    url += "&LIST_BZ_PROCS_STA=" + $c.stf.getObjectValue(edt_BzSDate);
    url += "&LIST_BZ_PROCS_END=" + $c.stf.getObjectValue(edt_BzEDate);
    url += "&DEP_CD=" + $c.stf.getObjectValue(cmb_DEP_CD);
    url += "&EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO);
    //url += "&UP_DEP_CD=" + js_belngdepcd;
    //url += "&LD_MKT_TP_CD="+gLdMktTp;
    //alert("vListMdCd :"+vListMdCd);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};
scwin.fn_setContnId = function(obj) {
    if (eval(obj) > 0) {
        //그리드에서 선택시
        scwin.clickBzProcsNo = dts_List.getCellData(eval(obj), "BZ_PROCS_NO");
        if (dts_List.getCellData(eval(obj), "PROCS_STAT_NM") == "접수") {
            scwin.clickListProcsStatCd = "10";
        }
    } else {
        scwin.clickBzProcsNo = "";
        scwin.clickListProcsStatCd = "";
    }
};
scwin.fn_OpenDetail = async function(row) {
    scwin.fn_setContnId(row);
    if (row < 0) {
        //그리드에서 선택시
        scwin.clickBzProcsNo = ""; //초기화

    }
    var hight = "290";
    var pageNM = "ULDSTF05981";
    await $c.frame.CreateDialogFrame("SPAC해제조치", "/lstproc/" + pageNM + ".gfm", "SPAC해제조치", 240, 200, 745, hight, "window");
};
scwin.fn_ExcelDown = function() {
    $c.data.downloadGridViewExcel(grd_List, "SPAC해제조치", "", "2"); //

};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD);
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EMP_NO, '');
    }
    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
    dts_EMP_NO.sort("DEP_CD", 0);
    //dts_EMP_NO.sort(); // W-Craft 주석처리 

};
scwin.dts_DEP_CD_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(cmb_DEP_CD, js_dep_cd);
};
scwin.dts_DEP_CD_OnLoadError = function() {
    $c.stf.alert_error(dts_DEP_CD);
};
scwin.dts_EMP_NO_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(cmb_EMP_NO, js_emp_no);
};
scwin.dts_EMP_NO_OnLoadError = function() {
    $c.stf.alert_error(dts_EMP_NO);
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "DEP_CD") == scwin.gDepCd || dts_EMP_NO.getCellData(row, "DEP_CD") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_BzSDate, edt_BzEDate);
};
scwin.img_COM_NM_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
};
scwin.img_BzSDate_onclick = function() {
    popUpCalendar2(edt_BzSDate);
};
scwin.img_BzEDate_onclick = function() {
    popUpCalendar2(edt_BzEDate);
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List);
    edt_TotalCnt.setValue("총 " + dts_List.getTotalRow() + " 건");
};
scwin.grd_List_OnDblClick = function(row, colid) {
    scwin.fn_OpenDetail(row);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_New_onclick = function() {
    scwin.fn_OpenDetail(-999);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    var vCurMonth = $c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 2);
    edt_BzSDate.setValue(vCurMonth);
    edt_BzEDate.setValue(vCurDate);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_SetCode();
    //fn_Search();

};
